# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety-gated target verification, hysteretic steering, and bounded reacquisition."""
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan = memory.get("scan_direction", "SCAN_LEFT")
    previous = memory.get("last_action", "")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_conf = float(observation["target_confidence"])
    identity_conf = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost = int(observation["lost_steps"])
    safety = float(observation["safety_confidence"])
    closing = float(observation["closing_risk"])

    def finish(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    if safety < 0.60 or closing >= 0.75:
        return finish("STOP", 0.99, "STOPPED")

    confirmed = visible and target_conf >= 0.55 and identity_conf >= 0.60
    if not confirmed:
        if state in {"LOCKED", "APPROACH", "REACQUIRE"} or lost > 0:
            if lost <= 1:
                return finish("STOP", 0.92, "REACQUIRE")
            next_scan = "SCAN_RIGHT" if scan == "SCAN_LEFT" else "SCAN_LEFT"
            memory["scan_direction"] = next_scan
            return finish(scan, 0.75, "SEARCH")
        next_scan = "SCAN_RIGHT" if scan == "SCAN_LEFT" else "SCAN_LEFT"
        memory["scan_direction"] = next_scan
        return finish(scan, 0.75, "SEARCH")

    if track_age < 2:
        return finish("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        if abs(float(observation["heading_error"])) <= 15.0 and identity_conf >= 0.80:
            return finish("ARRIVED", 0.96, "ARRIVED")
        action = "VEER_LEFT" if bearing < 0 else "VEER_RIGHT"
        return finish(action, 0.88, "APPROACH")

    left = bool(observation["corridor_left"])
    right = bool(observation["corridor_right"])
    center = bool(observation["corridor_center"])

    # Keep a recent turn near the decision boundary to avoid oscillation.
    if bearing < -12.0 and left:
        action = "VEER_LEFT"
    elif bearing > 12.0 and right:
        action = "VEER_RIGHT"
    elif abs(bearing) <= 16.0 and previous in {"VEER_LEFT", "VEER_RIGHT"}:
        action = previous if ((previous == "VEER_LEFT" and bearing < 4.0) or
                              (previous == "VEER_RIGHT" and bearing > -4.0)) else "FORWARD"
    elif center:
        action = "FORWARD"
    elif left:
        action = "VEER_LEFT"
    elif right:
        action = "VEER_RIGHT"
    else:
        return finish("STOP", 0.98, "STOPPED")

    return finish(action, 0.90 if action == "FORWARD" or abs(bearing) > 12.0 else 0.82,
                  "APPROACH")


# EVOLVE-BLOCK-END
